---
import type { HTMLAttributes } from "astro/types"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

import {
  formatPriceDiscount,
  formatPriceValue,
  parseSinglePriceValue,
  type DiscountFormat,
  type PriceValue,
} from "./format-price-value"

type Props = VariantProps<typeof variants> &
  HTMLAttributes<"span"> & {
    price?: PriceValue
    compareAt?: PriceValue
    currency?: string
    locale?: string
    variant?: "default" | "sale"
    discountFormat?: DiscountFormat
    showDiscount?: boolean
    discountLabel?: string
  }

const variants = cva("leading-tight", {
  variants: {
    variant: {
      default: "text-foreground",
      sale: "text-muted-foreground line-through",
    },
  },
})

const {
  class: className,
  price,
  compareAt,
  currency = "USD",
  locale = "en-US",
  variant = "default",
  discountFormat = "percentage",
  showDiscount = true,
  discountLabel = "Save",
  "data-slot": dataSlot = "price-value",
  ...props
} = Astro.props

const formattedPrice = formatPriceValue(price, { currency, locale })
const currentValue = parseSinglePriceValue(price)
const compareAtValue = parseSinglePriceValue(compareAt)
// A compare-at price only shows when it is higher than the price.
const formattedCompareAt =
  currentValue !== null &&
  compareAtValue !== null &&
  compareAtValue <= currentValue
    ? null
    : formatPriceValue(compareAt, { currency, locale })
const formattedDiscount =
  showDiscount && formattedCompareAt !== null
    ? formatPriceDiscount(price, compareAt, {
        currency,
        locale,
        format: discountFormat,
      })
    : null
---

{formattedPrice !== null && (
  <span
    class={cn("inline-flex flex-wrap items-center gap-x-2 gap-y-1", className)}
    data-slot={dataSlot}
    data-variant={variant}
    {...props}
  >
    <span class={cn(variants({ variant }))}>{formattedPrice}</span>
    {formattedCompareAt !== null && (
      <del class="text-muted-foreground text-sm leading-tight line-through">
        {formattedCompareAt}
      </del>
    )}
    {formattedDiscount !== null && (
      <span class="rounded-full bg-muted px-2 py-0.5 text-[0.625rem] font-medium text-foreground">
        {discountLabel} {formattedDiscount}
      </span>
    )}
  </span>
)}

export interface FormatPriceValueOptions {
  currency: string
  locale: string
}

export type PriceValue = number | string | [number, number]
export type DiscountFormat = "percentage" | "amount"

function formatCurrency(value: number, options: FormatPriceValueOptions) {
  return new Intl.NumberFormat(options.locale, {
    style: "currency",
    currency: options.currency,
  }).format(value)
}

export function parseSinglePriceValue(price: PriceValue | null | undefined) {
  if (price === null || price === undefined || price === "") {
    return null
  }

  if (typeof price === "number") {
    return Number.isFinite(price) ? price : null
  }

  if (Array.isArray(price)) {
    return null
  }

  const numericValue = Number(price)

  if (!Number.isNaN(numericValue) && Number.isFinite(numericValue)) {
    return numericValue
  }

  return null
}

export function formatPriceDiscount(
  price: PriceValue | null | undefined,
  compareAt: PriceValue | null | undefined,
  options: FormatPriceValueOptions & {
    format?: DiscountFormat
  }
) {
  const currentPrice = parseSinglePriceValue(price)
  const originalPrice = parseSinglePriceValue(compareAt)

  if (
    currentPrice === null ||
    originalPrice === null ||
    originalPrice <= currentPrice ||
    originalPrice <= 0
  ) {
    return null
  }

  if (options.format === "amount") {
    return formatCurrency(originalPrice - currentPrice, options)
  }

  return `${Math.round(((originalPrice - currentPrice) / originalPrice) * 100)}%`
}

export function formatPriceValue(
  price: PriceValue | null | undefined,
  options: FormatPriceValueOptions
) {
  if (price === null || price === undefined || price === "") {
    return null
  }

  if (typeof price === "number") {
    return formatCurrency(price, options)
  }

  if (Array.isArray(price)) {
    const [minimum, maximum] = price
    return `${formatCurrency(minimum, options)} - ${formatCurrency(maximum, options)}`
  }

  const rangeMatch = price.match(
    /^\s*(-?\d+(?:\.\d+)?)\s*-\s*(-?\d+(?:\.\d+)?)\s*$/
  )

  if (!rangeMatch) {
    return price
  }

  const [, minimum, maximum] = rangeMatch
  return `${formatCurrency(Number(minimum), options)} - ${formatCurrency(Number(maximum), options)}`
}
